<script setup lang="ts">import{ref}from'vue';import{ask,err,isDemo,type AskResult}from'./api';const question=ref(''),running=ref(false),cancel=ref<AbortController>(),result=ref<AskResult>(),error=ref<any>(),state=ref('');async function submit(){if(isDemo()){error.value={message:'演示模式只展示模拟流；真实问答请求未被伪装为成功。'};return}cancel.value?.abort();cancel.value=new AbortController();running.value=true;error.value=null;state.value='正在检索并汇总…';try{result.value=await ask({question:question.value,filters:{},timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,answer_mode:'concise',client_request_id:crypto.randomUUID()},cancel.value.signal);state.value='已完成'}catch(e:any){if(e.name==='AbortError')state.value='已取消，未自动重试。';else error.value=err(e)}finally{running.value=false}}function stop(){cancel.value?.abort()}</script><template><section><h1>研究问答</h1><p class="muted">回答基于明确条件与来源；服务未提供流时会报告真实错误。</p><label>你的问题<textarea v-model="question" class="control" rows="4" placeholder="例如：本周有哪些智能体工具发布？"></textarea></label><div class="row"><button :disabled="running||!question" @click="submit">开始分析</button><button v-if="running" @click="stop">取消</button></div><p aria-live="polite">{{state}}</p><div v-if="error" class="card error" role="alert">{{error.code||'请求失败'}}：{{error.message}}</div><article v-if="result" class="card"><h2>回答</h2><p>{{result.answer||'没有可回答的资料。'}}</p><p class="meta">完整匹配 {{result.scope_total}} · 取回 {{result.retrieved_count}} · 总结 {{result.summarized_count}} · 引用 {{result.citation_count}} · 覆盖：{{result.coverage}}</p><h2>引用来源</h2><ul><li v-for="c in result.citations"><a :href="c.source_url" target="_blank" rel="noopener">{{c.title}}</a></li></ul></article></section></template>
